(() => {
'use strict';
const BANK = window.IELTS_BANK;
const test = BANK.readingTest;
const listeningTest = BANK.listeningTest;
const writingTest = BANK.writingTest;
let sourceIndex = BANK.publicIndex;
const qByNum = new Map(test.questions.map(q => [q.number, q]));
const STORE = {reading:'ielts-practice-reading-v1',listening:'ielts-practice-listening-v1',writing:'ielts-practice-writing-v1',speaking:'ielts-practice-speaking-v1',feedback:'ielts-practice-feedback-v1',history:'ielts-practice-history-v2',contrast:'ielts-practice-contrast-v1'};
const $ = (s,root=document) => root.querySelector(s);
const main = $('#main');
const escapeHtml = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load = (key,fallback) => {try {return JSON.parse(localStorage.getItem(key)) ?? fallback;} catch{return fallback;}};
const save = (key,val) => {try {localStorage.setItem(key,JSON.stringify(val));if(key===STORE.reading||key===STORE.listening||key===STORE.writing)syncHistoryAttempt(key,val);}catch{toast('本地保存失败，请检查浏览器存储空间。');}};
const normalize = v => String(v ?? '').trim().replace(/\s+/g,' ').toLowerCase();
const isCorrect = (answer,expected) => normalize(answer) === normalize(expected);
const dateText = value => new Date(value).toLocaleString('zh-CN',{hour12:false});
const st={view:'season',passage:0,selectedQuestion:1,reading:load(STORE.reading,null),listening:load(STORE.listening,null),writing:load(STORE.writing,null),speaking:load(STORE.speaking,{}),feedback:load(STORE.feedback,{}),capabilities:{codexCli:false,speechToText:false},history:load(STORE.history,[]),historyId:null,listenSection:0,writeTask:0,month:'all',part:'all',wrongOnly:false,toastTimer:null};
const annotations=window.IELTS_ANNOTATIONS.create({
  getAttempt:kind=>kind==='reading'?st.reading:kind==='listening'?st.listening:kind==='pdf'?window.IELTS_PDF_IMPORT.getActivePaper():null,
  persist:kind=>kind==='pdf'?window.IELTS_PDF_IMPORT.persist():save(STORE[kind],kind==='reading'?st.reading:st.listening),
  toast
});
window.IELTS_ANNOTATIONS_INSTANCE=annotations;
if(load(STORE.contrast,false))document.body.classList.add('high-contrast');
function updateSourceLabels(){const season=sourceIndex.season;$('#today-label').textContent=`资料核对：${sourceIndex.checkedAt||'待更新'}`;$('#season-label').textContent=season?`${season.start.slice(0,4)} · ${season.start.slice(5,7)}—${season.end.slice(5,7)}`:'当期公开资料';}
updateSourceLabels();
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('show');clearTimeout(st.toastTimer);st.toastTimer=setTimeout(()=>e.classList.remove('show'),3000);}
function aiStatus(){return st.capabilities.codexCli?'已连接本机 Codex CLI。点击评分或纠错才会发送该次作答。':'未启用 AI 评分。若要使用，请在自己的电脑安装并登录 Codex CLI，再运行本项目的本地服务。';}
function feedbackHtml(value,basis='文本'){if(!value)return '';return `<div class="ai-result"><h4>Codex 练习反馈 ${value.estimatedBand===null?'':`· ${escapeHtml(basis)}估计 ${escapeHtml(value.estimatedBand)} 分`}</h4><p>${escapeHtml(value.summary)}</p>${value.criteria.map(c=>`<p><strong>${escapeHtml(c.name)}${c.estimate===null?'':` · ${escapeHtml(c.estimate)}`}</strong>：${escapeHtml(c.feedback)}</p>`).join('')}<p><strong>修改建议：</strong>${escapeHtml(value.correction)}</p><p><strong>下一步：</strong>${escapeHtml(value.nextStep)}</p><p class="small muted">${escapeHtml(value.limitations)}</p></div>`;}
function feedbackSlot(key,kind,id){return `<div id="feedback-${escapeHtml(key)}">${feedbackHtml(st.feedback[key])}</div>${st.capabilities.codexCli?`<button class="btn secondary ai-button" data-ai-kind="${kind}" data-ai-id="${escapeHtml(id)}">${kind==='writing'||kind==='speaking'?'获取 AI 练习评分':'用 AI 解释这道错题'}</button>`:''}`;}
async function requestFeedback(button){const kind=button.dataset.aiKind,id=button.dataset.aiId,key=`${kind}-${id}`,slot=$(`#feedback-${CSS.escape(key)}`);let payload={kind};if(kind==='reading'||kind==='listening'){payload.questionNumber=Number(id);payload.answer=(kind==='reading'?st.reading:st.listening)?.answers[id]||'';}else if(kind==='writing'){payload.taskId=id;payload.answer=st.writing?.revisions[id]?.trim()||st.writing?.drafts[id]||'';}else if(kind==='speaking'){payload.topicId=id;payload.answer=st.speaking[id]||'';}button.disabled=true;button.textContent='生成中…';try{const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'请求失败');st.feedback[key]=result.feedback;save(STORE.feedback,st.feedback);if(slot)slot.innerHTML=feedbackHtml(result.feedback);}catch(error){if(slot)slot.textContent=`反馈未生成：${error.message}`;}finally{button.disabled=false;button.textContent=kind==='writing'||kind==='speaking'?'重新评分':'重新解释';}}
async function refreshCapabilities(){if(!location.protocol.startsWith('http'))return;try{const response=await fetch('/api/capabilities',{cache:'no-store'});if(!response.ok)return;const next=await response.json();if(st.capabilities.codexCli!==!!next.codexCli||st.capabilities.speechToText!==!!next.speechToText){st.capabilities=next;render();}}catch{}}
function nav(view){annotations.dismiss();if(st.view==='season'&&view!=='season')window.IELTS_SEASON_BANK.deactivate();if(st.view==='speaking'&&view!=='speaking'&&recorder?.state==='recording')stopRecording();if(st.view!==view)st.wrongOnly=false;if(view==='history'&&st.view!=='history')st.historyId=null;st.view=view;document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();window.scrollTo({top:0,behavior:'instant'});}
function header(kicker,title,lede,right=''){return `<div class="page-head"><div><p class="kicker">${escapeHtml(kicker)}</p><h1>${escapeHtml(title)}</h1><p class="lede">${escapeHtml(lede)}</p></div>${right}</div>`;}
function renderHome(){const read=sourceIndex.reading.length,audio=sourceIndex.listening.length;main.innerHTML=`
${header('Your practice workspace','当季题库与练习记录',`${sourceIndex.season.label}四科当期资料在题库首页；原创模考作为补充练习。练习记录保存在浏览器。`,'<span class="badge warn">非官方独立练习系统</span>')}
<div class="notice blue"><strong>优先练当季：</strong>四科公开线索和独立编写的当季练习已放在题库首页。<button class="btn ghost" data-action="open-season">打开当季四科题库 →</button></div>
<div class="stat-row"><div class="stat"><strong>${read}</strong><span>本期阅读重建练习入口</span></div><div class="stat"><strong>${audio}</strong><span>本期听力重建练习入口</span></div><div class="stat"><strong>${sourceIndex.speaking?.length||0}</strong><span>本期第三方口语话题入口</span></div><div class="stat"><strong>${sourceIndex.writing.filter(x=>x.kind==='third_party_dated_topic').length}</strong><span>本期第三方写作话题入口</span></div></div>
<div class="section-title"><h2>原创模考 · 补充练习</h2><span class="muted small">浏览器本地保存 · 无需账号</span></div>
<div class="card-grid"><section class="card"><div class="card-icon">▣</div><h2>阅读模考</h2><p>原创学术类阅读：3 篇文章、40 题、60 分钟。跳题、标记、自动保存、提交后逐题改错。</p><footer><button class="btn" data-action="open-reading">进入阅读 →</button></footer></section>
<section class="card"><div class="card-icon">♫</div><h2>听力练习</h2><p>4 段原创合成语音、40 题，提交后显示文字稿、答案和修正栏。为缩时练习，音频短于正式考试。</p><footer><button class="btn" data-action="open-listening">进入听力 →</button></footer></section>
<section class="card"><div class="card-icon">✎</div><h2>写作练习</h2><p>原创 Task 1 表格与 Task 2 议论文。60 分钟、字数统计、初稿保存和提交后修订。</p><footer><button class="btn" data-action="open-writing">进入写作 →</button></footer></section>
<section class="card"><div class="card-icon">◉</div><h2>口语话题练习</h2><p>查看本期大陆口语话题目录；可录音回放并保存转写文本。有 Codex CLI 时可获取文本反馈。</p><footer><button class="btn" data-action="open-speaking">进入口语 →</button></footer></section>
</div>
<div class="section-title"><h2>公开题库</h2></div><div class="notice blue">当前资料期：${escapeHtml(sourceIndex.season.label)}。每天检查新来源；到下一资料期时当前索引重建，未发生的考试不会列为考后真题。<button class="btn ghost" data-action="open-library">查看资料和来源 →</button></div>
<div class="notice" style="margin-top:13px">这不是 NEEA 或 IELTS 官方系统。离线练习题与音频为原创。${escapeHtml(aiStatus())} AI 分数只是练习估计。</div>`;}
function readingIntro(){main.innerHTML=`${header('Reading practice','学术类阅读模考','先阅读说明，再开始倒计时。答题记录会自动保存在这个浏览器中。','<span class="badge blue">3 passages · 40 questions</span>')}
<div class="panel"><h2>${escapeHtml(test.title)}</h2><p style="margin:10px 0 16px">${escapeHtml(test.notice)}</p><div class="notice">开始后倒计时 60 分钟；可在题号栏跳题、标记待查。时间结束自动交卷。提交后会保留初次分数，并允许逐题改正，改正不会覆盖初次分数。</div><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:20px"><button class="btn" data-action="start-reading">开始 60 分钟模考</button><button class="btn secondary" data-action="open-library">看公开题库入口</button></div></div>`;}
function renderReading(){if(!st.reading){readingIntro();return;}if(st.reading.submittedAt){renderReview();return;}renderExam();}
function deadlineMs(){return st.reading?.deadlineAt-Date.now() || 0;}
function timerText(ms){let s=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function renderExam(){annotations.dismiss();const passage=test.passages[st.passage],qs=test.questions.filter(q=>q.passage===passage.id),r=st.reading;main.innerHTML=`
<div class="reading-head"><div><small>ACADEMIC READING · PASSAGE ${st.passage+1} / 3</small><h1>${escapeHtml(test.title)}</h1></div><div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap"><span class="timer" id="reading-timer">${timerText(deadlineMs())}</span><button class="btn secondary" data-action="prev-passage" ${st.passage===0?'disabled':''}>← 上篇</button><button class="btn secondary" data-action="next-passage" ${st.passage===2?'disabled':''}>下篇 →</button><button class="btn danger" data-action="submit-reading">交卷</button></div></div>
<div class="notice blue" style="margin-bottom:13px">原创练习 · 非官方真题。选中或双击原文、题干，可做三色高光或选词笔记；单击标注后选择取消。点击题号可跳转，旗标用于回看。</div>
<div class="reading-layout"><article class="passage" id="passage-scroll" style="--passage-font:${Math.min(22,Math.max(14,r.fontSize||16))}px"><h2>${escapeHtml(passage.title)}</h2><div class="passage-sub">${escapeHtml(passage.subtitle)}</div><div class="reading-tools"><span>原文显示</span><button type="button" data-action="font-decrease" aria-label="缩小阅读字体">A−</button><span id="passage-font-label">${r.fontSize||16}px</span><button type="button" data-action="font-increase" aria-label="放大阅读字体">A+</button></div>${passage.paragraphs.map(p=>`<p><b>${escapeHtml(p.label)}</b>${annotations.textHtml('reading',`p:${passage.id}:${p.label}`,p.text)}</p>`).join('')}</article>
<section class="questions" id="questions-scroll"><h2>Questions ${qs[0].number}–${qs.at(-1).number}</h2>${qs.map(questionHtml).join('')}</section></div>
<div class="exam-nav"><span class="progress-caption" id="reading-progress">已答 ${Object.values(r.answers).filter(v=>normalize(v)).length} / 40</span><div class="number-grid">${test.questions.map(q=>`<button type="button" data-jump="${q.number}" class="${normalize(r.answers[q.number])?'answered':''} ${r.flags.includes(q.number)?'flagged':''} ${st.selectedQuestion===q.number?'current':''}" title="第 ${q.number} 题">${q.number}</button>`).join('')}</div></div>${annotations.drawerHtml('reading',passage.id)}`;
if(st.selectedQuestion && qs.some(q=>q.number===st.selectedQuestion))setTimeout(()=>$('#q-'+st.selectedQuestion)?.scrollIntoView({block:'nearest'}),0);}
function questionHtml(q){const value=st.reading.answers[q.number]||'';let control='';if(q.type==='text'){control=`<input type="text" data-answer="${q.number}" value="${escapeHtml(value)}" autocomplete="off" aria-label="第 ${q.number} 题答案">`;}else if(q.type==='tfng'){control=['TRUE','FALSE','NOT GIVEN'].map(v=>`<label><input type="radio" name="q${q.number}" value="${v}" data-answer="${q.number}" ${value===v?'checked':''}>${annotations.textHtml('reading',`q:${q.number}:opt:${v}`,v)}</label>`).join('');}else{control=q.options.map(o=>{const key=o.split('.')[0];return `<label><input type="radio" name="q${q.number}" value="${escapeHtml(key)}" data-answer="${q.number}" ${value===key?'checked':''}>${annotations.textHtml('reading',`q:${q.number}:opt:${key}`,o)}</label>`}).join('');}return `<div class="question" id="q-${q.number}"><div class="q-top"><span class="q-num">${q.number}</span><div class="q-prompt">${annotations.textHtml('reading',`q:${q.number}`,q.prompt)}</div></div><div class="q-control">${control}</div><div class="q-actions"><button type="button" class="flag-btn ${st.reading.flags.includes(q.number)?'on':''}" data-flag="${q.number}">${st.reading.flags.includes(q.number)?'⚑ 已标记':'⚐ 标记待查'}</button></div></div>`;}
function startReading(){st.reading={testId:test.id,startedAt:Date.now(),deadlineAt:Date.now()+test.durationMinutes*60000,answers:{},flags:[],corrections:{},notes:{},annotations:{},fontSize:16,submittedAt:null};st.passage=0;st.selectedQuestion=1;save(STORE.reading,st.reading);renderReading();}
function submitReading(auto=false){if(!st.reading||st.reading.submittedAt)return;const blank=40-Object.values(st.reading.answers).filter(v=>normalize(v)).length;if(!auto&&blank&&!window.confirm(`仍有 ${blank} 题未作答。确定交卷吗？`))return;st.reading.submittedAt=Date.now();st.reading.autoSubmitted=auto;save(STORE.reading,st.reading);const entry={id:`reading-${st.reading.startedAt}`,type:'reading',title:test.title,at:st.reading.submittedAt,score:score(),total:40};addHistory(entry);if(st.view==='reading')renderReview();toast(auto?'时间到，已自动交卷':'已交卷，可逐题核对并改错');}
function score(){return test.questions.reduce((n,q)=>n+(isCorrect(st.reading.answers[q.number],q.answer)?1:0),0);}
function renderReview(){const r=st.reading,raw=score(),fixed=test.questions.reduce((n,q)=>n+(isCorrect(r.corrections[q.number]??r.answers[q.number],q.answer)?1:0),0);main.innerHTML=`${header('Answer review','提交后核对与改错','初次得分固定保留。可在错题下填写修正答案，立即查看是否改对；解析给出原文段落位置。','<span class="badge">非官方练习评分</span>')}
<div class="review-overview"><div class="score-box"><strong>${raw} / 40</strong><span>初次正确题数</span></div><div class="score-box"><strong id="corrected-score">${fixed} / 40</strong><span>包含修正后的正确题数</span></div><div class="score-box"><strong>${dateText(r.submittedAt)}</strong><span>交卷时间</span></div></div>
<div class="toolbar" style="margin-top:20px"><button class="btn ${st.wrongOnly?'':'secondary'}" data-action="toggle-wrong">${st.wrongOnly?'显示全部题目':'只看错题'}</button><button class="btn secondary" data-action="export-result">导出作答与改错 JSON</button><button class="btn secondary" data-action="restart-reading">重新开始原创模考</button></div>
<div class="notice">自动核对只适用于这份原创阅读练习。错题中的“修正答案”是复盘记录，不会重写初次成绩。文字填空忽略大小写和多余空格，其他拼写必须与答案一致。</div>
${test.passages.map((p,i)=>{const all=test.questions.filter(q=>q.passage===p.id),shown=st.wrongOnly?all.filter(q=>!isCorrect(r.answers[q.number],q.answer)):all;return shown.length?`<div class="section-title"><h2>Passage ${i+1} · ${escapeHtml(p.title)}</h2><span class="badge blue">${all.filter(q=>isCorrect(r.answers[q.number],q.answer)).length} / ${all.length} 正确</span></div>${shown.map(reviewCard).join('')}`:''}).join('')}`;}
function reviewCard(q){const r=st.reading,answer=r.answers[q.number]||'',okay=isCorrect(answer,q.answer),corrected=r.corrections[q.number]??'';return `<article class="review-card ${okay?'':'wrong'}" id="review-${q.number}"><h3>${q.number}. ${escapeHtml(q.prompt)}</h3><p>初次作答：<span class="answer-pill ${okay?'right':'wrong'}">${escapeHtml(answer||'未作答')}</span>　标准答案：<span class="answer-pill right">${escapeHtml(q.answer)}</span></p><p>定位：Passage ${escapeHtml(q.passage.slice(-1))} · 段落 ${escapeHtml(q.evidence)}。${escapeHtml(q.explanation)}</p>${!okay?`<div class="correction-row"><input type="text" data-correction-input="${q.number}" value="${escapeHtml(corrected)}" placeholder="输入你修正后的答案" aria-label="第 ${q.number} 题修正答案"><button class="btn secondary" data-correct="${q.number}">检查修正</button></div><div class="correction-result" id="correction-result-${q.number}">${corrected?(isCorrect(corrected,q.answer)?'✓ 已改对':'仍需检查拼写或选项'):'请自己重新作答，再核对答案。'}</div>${feedbackSlot(`reading-${q.number}`,'reading',q.number)}`:''}</article>`;}
function correctQuestion(n){const input=$(`[data-correction-input="${n}"]`);if(!input)return;st.reading.corrections[n]=input.value.trim();save(STORE.reading,st.reading);const result=$(`#correction-result-${n}`);result.textContent=isCorrect(input.value,qByNum.get(n).answer)?'✓ 已改对':'仍需检查拼写或选项';result.style.color=isCorrect(input.value,qByNum.get(n).answer)?'#2a7c61':'#b35246';const fixed=test.questions.reduce((total,q)=>total+(isCorrect(st.reading.corrections[q.number]??st.reading.answers[q.number],q.answer)?1:0),0);const count=$('#corrected-score');if(count)count.textContent=`${fixed} / 40`;}
const copy = value => JSON.parse(JSON.stringify(value));
function historyPaper(type){const bank=type==='reading'?test:type==='listening'?listeningTest:writingTest;return copy(type==='reading'?{id:bank.id,questions:bank.questions,passages:bank.passages}:type==='listening'?{id:bank.id,questions:bank.questions,sections:bank.sections.map(s=>({id:s.id,title:s.title,transcript:s.transcript}))}:{id:bank.id,tasks:bank.tasks});}
function syncHistoryAttempt(key,val){if(!val?.submittedAt)return;const type=key===STORE.reading?'reading':key===STORE.listening?'listening':'writing',entry=st.history.find(x=>x.id===`${type}-${val.startedAt}`);if(!entry)return;entry.attempt=copy(val);localStorage.setItem(STORE.history,JSON.stringify(st.history));}
function addHistory(entry){const attempt=st[entry.type];entry.attempt=copy(attempt);entry.paper=historyPaper(entry.type);const pos=st.history.findIndex(x=>x.id===entry.id);if(pos>=0)st.history[pos]=entry;else st.history.unshift(entry);save(STORE.history,st.history);}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function listeningIntro(){main.innerHTML=`${header('Listening practice','学术类听力练习','4 个短场景、40 题。音频为本地合成语音，文字稿在提交后显示。','<span class="badge blue">4 sections · 40 questions</span>')}<div class="panel"><h2>${escapeHtml(listeningTest.title)}</h2><p style="margin:10px 0 16px">${escapeHtml(listeningTest.notice)}</p><div class="notice">练习计时 30 分钟，可暂停或重播音频。音频总时长短于正式考试，适合集中练题型；答题会自动保存在此浏览器。</div><button class="btn" data-action="start-listening" style="margin-top:18px">开始听力练习</button></div>`;}
function renderListening(){annotations.dismiss();if(!st.listening){listeningIntro();return;}if(st.listening.submittedAt){renderListeningReview();return;}const section=listeningTest.sections[st.listenSection],questions=listeningTest.questions.filter(q=>q.section===section.id),r=st.listening;main.innerHTML=`<div class="reading-head"><div><small>ACADEMIC LISTENING · SECTION ${st.listenSection+1} / 4</small><h1>${escapeHtml(section.title)}</h1></div><div class="exam-head-actions"><span class="timer" id="listening-timer">${timerText(r.deadlineAt-Date.now())}</span><button class="btn danger" data-action="submit-listening">交卷</button></div></div><div class="notice blue">原创缩时练习 · ${escapeHtml(section.kind)}。请播放音频后作答；交卷前不显示文字稿。选中或双击题干可做三色高光或选词笔记，单击标注后选择取消。</div><div class="panel listening-player"><audio controls preload="metadata" src="${escapeHtml(section.audio)}" aria-label="第 ${st.listenSection+1} 段听力音频"></audio><p>可以重听、暂停和切换章节。若直接双击 HTML 文件时音频无法播放，请按 README 用本地服务器打开。</p></div><div class="listening-questions"><h2>Questions ${questions[0].number}–${questions.at(-1).number}</h2>${questions.map(listeningQuestionHtml).join('')}</div><div class="exam-nav"><span class="progress-caption" id="listening-progress">已答 ${Object.values(r.answers).filter(v=>normalize(v)).length} / 40</span><div class="number-grid">${listeningTest.questions.map(q=>`<button data-listen-jump="${q.number}" class="${normalize(r.answers[q.number])?'answered':''}" title="第 ${q.number} 题">${q.number}</button>`).join('')}</div></div>${annotations.drawerHtml('listening')}`;}
function listeningQuestionHtml(q){const value=st.listening.answers[q.number]||'';const control=q.type==='text'?`<input type="text" data-listen-answer="${q.number}" value="${escapeHtml(value)}" autocomplete="off" aria-label="第 ${q.number} 题答案">`:q.options.map(o=>{const key=o.split('.')[0];return `<label><input type="radio" name="lq${q.number}" value="${escapeHtml(key)}" data-listen-answer="${q.number}" ${value===key?'checked':''}>${annotations.textHtml('listening',`q:${q.number}:opt:${key}`,o)}</label>`}).join('');return `<div class="question"><div class="q-top"><span class="q-num">${q.number}</span><div class="q-prompt">${annotations.textHtml('listening',`q:${q.number}`,q.prompt)}</div></div><div class="q-control">${control}</div></div>`;}
function startListening(){st.listening={testId:listeningTest.id,startedAt:Date.now(),deadlineAt:Date.now()+listeningTest.durationMinutes*60000,answers:{},corrections:{},annotations:{},submittedAt:null};st.listenSection=0;save(STORE.listening,st.listening);renderListening();}
function listenScore(corrected=false){return listeningTest.questions.reduce((n,q)=>n+(isCorrect(corrected?(st.listening.corrections[q.number]??st.listening.answers[q.number]):st.listening.answers[q.number],q.answer)?1:0),0);}
function submitListening(auto=false){if(!st.listening||st.listening.submittedAt)return;const blank=40-Object.values(st.listening.answers).filter(v=>normalize(v)).length;if(!auto&&blank&&!window.confirm(`听力还有 ${blank} 题未作答，确定交卷吗？`))return;st.listening.submittedAt=Date.now();save(STORE.listening,st.listening);addHistory({id:`listening-${st.listening.startedAt}`,type:'listening',title:listeningTest.title,at:st.listening.submittedAt,score:listenScore(),total:40});if(st.view==='listening')renderListeningReview();toast(auto?'听力时间到，已交卷':'听力已交卷');}
function renderListeningReview(){const r=st.listening;main.innerHTML=`${header('Listening review','听力答案与改错','初次成绩保留；逐题修正会更新复盘正确数。文字稿仅供提交后核对。','<span class="badge">非官方练习评分</span>')}<div class="review-overview"><div class="score-box"><strong>${listenScore()} / 40</strong><span>初次正确题数</span></div><div class="score-box"><strong id="listen-corrected-score">${listenScore(true)} / 40</strong><span>修订后正确题数</span></div></div><div class="toolbar" style="margin-top:20px"><button class="btn secondary" data-action="export-listening">导出作答 JSON</button><button class="btn secondary" data-action="restart-listening">重新开始</button></div>${listeningTest.sections.map((section,i)=>`<div class="section-title"><h2>Section ${i+1} · ${escapeHtml(section.title)}</h2></div><details class="transcript"><summary>查看本段文字稿</summary><p>${escapeHtml(section.transcript)}</p></details>${listeningTest.questions.filter(q=>q.section===section.id).map(q=>{const first=r.answers[q.number]||'',okay=isCorrect(first,q.answer),fixed=r.corrections[q.number]||'';return `<article class="review-card ${okay?'':'wrong'}"><h3>${q.number}. ${escapeHtml(q.prompt)}</h3><p>初次作答：<span class="answer-pill ${okay?'right':'wrong'}">${escapeHtml(first||'未作答')}</span>　参考答案：<span class="answer-pill right">${escapeHtml(q.answer)}</span></p><p>${escapeHtml(q.explanation)}</p>${okay?'':`<div class="correction-row"><input type="text" data-listen-correction="${q.number}" value="${escapeHtml(fixed)}" aria-label="第 ${q.number} 题修正答案"><button class="btn secondary" data-action="correct-listening" data-number="${q.number}">检查修正</button></div><div id="listen-correction-${q.number}" class="correction-result">${fixed?(isCorrect(fixed,q.answer)?'✓ 已改对':'仍需检查'):'请重新作答并检查。'}</div>`}</article>`}).join('')}`).join('')}`;}
const originalListeningReview=renderListeningReview;
renderListeningReview=()=>{originalListeningReview();const toolbar=$('.toolbar',main);toolbar.insertAdjacentHTML('afterbegin',`<button class="btn ${st.wrongOnly?'':'secondary'}" data-action="toggle-wrong">${st.wrongOnly?'显示全部题目':'只看错题'}</button>`);listeningTest.sections.forEach((section,i)=>{const transcript=main.querySelectorAll('.transcript')[i];if(section.sentences?.length){transcript.insertAdjacentHTML('afterend',`<details class="sentence-panel"><summary>逐句听 · ${section.sentences.length} 句</summary><audio controls preload="none" aria-label="逐句回听播放器"></audio><div class="sentence-list">${section.sentences.map(item=>`<button type="button" class="sentence-button" data-sentence-src="${escapeHtml(item.audio)}"><b>${item.number}.</b> ${escapeHtml(item.text)}</button>`).join('')}</div></details>`);}});main.querySelectorAll('.review-card').forEach(card=>{const number=Number(card.querySelector('h3')?.textContent.match(/^\d+/)?.[0]);const q=listeningTest.questions.find(item=>item.number===number);if(!q)return;if(st.wrongOnly&&!card.classList.contains('wrong'))card.hidden=true;if(card.classList.contains('wrong'))card.insertAdjacentHTML('beforeend',feedbackSlot(`listening-${number}`,'listening',number));});};
function correctListening(n){const q=listeningTest.questions.find(x=>x.number===n),input=$(`[data-listen-correction="${n}"]`);if(!q||!input)return;st.listening.corrections[n]=input.value.trim();save(STORE.listening,st.listening);$(`#listen-correction-${n}`).textContent=isCorrect(input.value,q.answer)?'✓ 已改对':'仍需检查';$('#listen-corrected-score').textContent=`${listenScore(true)} / 40`;}
function writingIntro(){main.innerHTML=`${header('Writing practice','学术类写作模考','原创 Task 1 和 Task 2，限时 60 分钟。提交后保留初稿，可逐题修改与自查。','<span class="badge blue">2 tasks · 60 minutes</span>')}<div class="panel"><h2>${escapeHtml(writingTest.title)}</h2><p style="margin:10px 0 16px">${escapeHtml(writingTest.notice)}</p><div class="notice">Task 1 建议约 20 分钟、至少 150 词；Task 2 建议约 40 分钟、至少 250 词。字数仅作提醒；已接入 Codex CLI 时，提交后可主动请求练习评分；未接入时可自行复盘。</div><button class="btn" data-action="start-writing" style="margin-top:18px">开始写作练习</button></div>`;}
function renderWriting(){if(!st.writing){writingIntro();return;}if(st.writing.submittedAt){renderWritingReview();return;}const task=writingTest.tasks[st.writeTask];main.innerHTML=`<div class="reading-head"><div><small>ACADEMIC WRITING · TASK ${st.writeTask+1} / 2</small><h1>${escapeHtml(writingTest.title)}</h1></div><div class="exam-head-actions"><span class="timer" id="writing-timer">${timerText(st.writing.deadlineAt-Date.now())}</span><button class="btn danger" data-action="submit-writing">交卷</button></div></div><div class="toolbar"><button class="btn ${st.writeTask===0?'':'secondary'}" data-write-task="0">Task 1 · 建议 20 分钟</button><button class="btn ${st.writeTask===1?'':'secondary'}" data-write-task="1">Task 2 · 建议 40 分钟</button></div><div class="writing-layout"><section class="panel"><p class="kicker">${escapeHtml(task.name)}</p><h2>题目</h2><p class="writing-prompt">${escapeHtml(task.prompt)}</p>${task.columns?`<table class="writing-table"><thead><tr>${task.columns.map(v=>`<th>${escapeHtml(v)}</th>`).join('')}</tr></thead><tbody>${task.rows.map(row=>`<tr>${row.map(v=>`<td>${escapeHtml(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="small muted">表格为原创虚构数据，单位：千次访问。</p>`:''}</section><section class="panel"><h2>答题区</h2><textarea id="writing-draft" class="draft writing-draft" placeholder="Write your answer in English...">${escapeHtml(st.writing.drafts[task.id]||'')}</textarea><p class="small muted">已写 <strong id="writing-word-count">${wordCount(st.writing.drafts[task.id]||'')}</strong> 词 · 建议至少 ${task.minimumWords} 词 · 自动保存</p></section></div>`;}
function wordCount(v){return String(v||'').trim().split(/\s+/).filter(Boolean).length;}
function startWriting(){st.writing={testId:writingTest.id,startedAt:Date.now(),deadlineAt:Date.now()+writingTest.durationMinutes*60000,drafts:{W1:'',W2:''},revisions:{W1:'',W2:''},checks:{},submittedAt:null};st.writeTask=0;save(STORE.writing,st.writing);renderWriting();}
function submitWriting(auto=false){if(!st.writing||st.writing.submittedAt)return;const missing=writingTest.tasks.filter(t=>!st.writing.drafts[t.id].trim()).length;if(!auto&&missing&&!window.confirm(`还有 ${missing} 道写作题未写，确定交卷吗？`))return;st.writing.submittedAt=Date.now();save(STORE.writing,st.writing);addHistory({id:`writing-${st.writing.startedAt}`,type:'writing',title:writingTest.title,at:st.writing.submittedAt,words:writingTest.tasks.map(t=>wordCount(st.writing.drafts[t.id]))});if(st.view==='writing')renderWritingReview();toast(auto?'写作时间到，已交卷':'写作已交卷，可继续修订');}
function renderWritingReview(){const w=st.writing;main.innerHTML=`${header('Writing review','初稿与修订','初稿保留在浏览器；修订稿可继续编辑。请对照题目和清单自行检查，不生成自动分数。','<span class="badge warn">自我复盘</span>')}<div class="toolbar"><button class="btn secondary" data-action="export-writing">导出初稿与修订 JSON</button><button class="btn secondary" data-action="restart-writing">重新开始</button></div>${writingTest.tasks.map(task=>`<section class="panel writing-review"><h2>${escapeHtml(task.name)}</h2><p class="writing-prompt">${escapeHtml(task.prompt)}</p><p class="small muted">初稿 ${wordCount(w.drafts[task.id])} 词 · 建议至少 ${task.minimumWords} 词</p><div class="original-draft">${escapeHtml(w.drafts[task.id]||'未填写')}</div><h3>修订稿</h3><textarea class="draft" data-write-revision="${task.id}" placeholder="Write a revised answer here...">${escapeHtml(w.revisions[task.id]||'')}</textarea><p class="small muted">修订稿 <span data-revision-count="${task.id}">${wordCount(w.revisions[task.id])}</span> 词 · 自动保存</p><div class="checklist">${task.review.map((item,i)=>`<label><input type="checkbox" data-write-check="${task.id}-${i}" ${w.checks[task.id+'-'+i]?'checked':''}>${escapeHtml(item)}</label>`).join('')}</div></section>`).join('')}`;}
const originalWritingReview=renderWritingReview;
renderWritingReview=()=>{originalWritingReview();$('.lede',main).textContent=`初稿保留在浏览器；修订稿可继续编辑。${aiStatus()}`;$('.page-head .badge',main).textContent=st.capabilities.codexCli?'可选 AI 练习评分':'自我复盘';main.querySelectorAll('.writing-review').forEach((section,i)=>{const task=writingTest.tasks[i];section.insertAdjacentHTML('beforeend',`<div class="ai-feedback-area"><p class="small muted">${escapeHtml(aiStatus())} ${st.capabilities.codexCli?'评分使用修订稿；如未修订则使用初稿。':''}</p>${feedbackSlot(`writing-${task.id}`,'writing',task.id)}</div>`);});};
let recorder=null,recordStream=null,recordingUrl=null,recordingBlob=null,recordingTopicId=null,recordingResult=null;
function seasonSpeakingCue(topic){if(window.IELTS_SEASON_CONTENT.seasonId!==sourceIndex.season.id)return '';const item=window.IELTS_SEASON_CONTENT.speaking.find(x=>x.sourceUrl===topic.url&&x.sourceTitle===topic.title);return item?`<div class="season-speaking-questions"><strong>当季独立编写练习问法</strong>${item.questions.map((question,i)=>`<p><b>${i+1}.</b> ${escapeHtml(question)}</p>`).join('')}</div>`:'';}
function renderSpeaking(){const topics=sourceIndex.speaking||[],topic=topics.find(x=>x.id===st.topicId)||topics[0];if(topic)st.topicId=topic.id;main.innerHTML=`${header('Speaking topics','当期口语话题练习',`${sourceIndex.season.label}第三方大陆话题目录；点开原站查看完整题卡。此处练习记录保存在浏览器。`,'<span class="badge blue">非官方话题索引</span>')}<div class="notice">${escapeHtml(aiStatus())} 录音评分会先在本机转写录音并测量语速与停顿，再由 Codex CLI 给出练习反馈。原始音频不会发送给 Codex；发音维度暂不评分。</div>${topics.length?`<div class="speaking-layout"><aside class="panel speaking-topics"><input id="topic-search" type="search" placeholder="搜索话题" aria-label="搜索口语话题"><select id="part-filter" aria-label="筛选口语 Part"><option value="all">全部 Part</option><option value="Part 1" ${st.part==='Part 1'?'selected':''}>Part 1</option><option value="Part 2 / Part 3" ${st.part==='Part 2 / Part 3'?'selected':''}>Part 2 / Part 3</option></select><div class="topic-list">${topics.map(x=>`<button type="button" class="topic-row ${x.id===topic.id?'active':''}" data-topic-id="${escapeHtml(x.id)}" data-topic-part="${escapeHtml(x.part)}"><small>${escapeHtml(x.part)}</small><span>${escapeHtml(x.title)}</span></button>`).join('')}</div></aside><div class="speaking-stage"><section class="cue"><p class="kicker">${escapeHtml(topic.part)} · 公开话题标题</p><h2>${escapeHtml(topic.title)}</h2><p>${topic.part==='Part 1'?'围绕这个话题，用英语回答个人经历和看法；每个回答可以练习 20—40 秒。':'围绕这个话题组织一段 1—2 分钟的回答，再补充原因、例子和延伸看法。完整题卡与具体追问请查看来源。'}</p>${seasonSpeakingCue(topic)}<a href="${escapeHtml(topic.url)}" target="_blank" rel="noopener noreferrer">查看原站题卡 ↗</a><div class="cue-actions"><button class="btn secondary" data-action="record-start">开始录音</button><button class="btn secondary" data-action="record-stop" disabled>停止录音</button><span class="record-status" id="record-status">录音只在当前页面临时保存</span></div><audio id="record-playback" controls hidden aria-label="口语录音回放"></audio>${st.capabilities.codexCli&&st.capabilities.speechToText?'<button class="btn secondary ai-button" data-action="score-recording" disabled>评分这段录音</button>':st.capabilities.codexCli?'<p class="small muted">要评分录音，请先安装本地转写组件：pip install -r requirements-speech.txt，然后重启服务。</p>':''}<div id="recording-feedback"></div><label for="speaking-transcript"><strong>文字作答（可选，单独评分）</strong></label><textarea id="speaking-transcript" class="draft" placeholder="Type what you actually said. Keep your original meaning and wording for useful feedback.">${escapeHtml(st.speaking[topic.id]||'')}</textarea><p class="small muted">文字自动保存在本浏览器。下方文字评分只读取这段文字；录音及其反馈刷新后会消失。${st.capabilities.codexCli?'文字至少 40 字符后可请求练习反馈。':'当前可继续录音与保存文本。'}</p>${feedbackSlot(`speaking-${topic.id}`,'speaking',topic.id)}</section></div></div>`:'<div class="empty">本期资料尚无已核对的大陆口语话题。更新器会在下次运行时重试来源。</div>'}`;if(recordingBlob&&recordingTopicId===topic?.id){const player=$('#record-playback');player.src=recordingUrl;player.hidden=false;const button=$('[data-action="score-recording"]');if(button)button.disabled=false;$('#record-status').textContent='录音已保存于当前页面，可回放或请求评分。';if(recordingResult)showRecordingResult(recordingResult);}}
function filterTopics(){const query=normalize($('#topic-search')?.value||'');main.querySelectorAll('.topic-row').forEach(row=>{row.hidden=(st.part!=='all'&&row.dataset.topicPart!==st.part)||!normalize(row.textContent).includes(query);});}
function showRecordingResult(result){const slot=$('#recording-feedback');if(!slot)return;const timing=result.timing;slot.innerHTML=`<div class="ai-result"><h4>录音转写与节奏</h4><p>${escapeHtml(result.transcript)}</p><p class="small muted">录音 ${escapeHtml(timing.durationSeconds)} 秒 · 约 ${escapeHtml(timing.wordsPerMinute??'—')} 词/分钟 · 停顿约 ${escapeHtml(timing.pauseCount)} 次（其中较长停顿 ${escapeHtml(timing.longPauseCount)} 次）。时间点来自自动转写，仅供练习参考。</p></div>${feedbackHtml(result.feedback,'录音部分')}`;}
async function requestRecordingFeedback(button){if(!recordingBlob||recordingTopicId!==st.topicId){toast('请先录制当前话题的回答');return;}const blob=recordingBlob,topicId=recordingTopicId;button.disabled=true;button.textContent='转写并评分中…';const slot=$('#recording-feedback');try{const response=await fetch('/api/speaking-audio',{method:'POST',headers:{'Content-Type':blob.type||'audio/webm','X-IELTS-Topic':topicId},body:blob});const result=await response.json();if(!response.ok)throw new Error(result.error||'录音评分失败');if(recordingBlob!==blob||recordingTopicId!==topicId)return;recordingResult=result;if(st.topicId===topicId)showRecordingResult(result);}catch(error){if(recordingBlob===blob&&recordingTopicId===topicId&&slot?.isConnected)slot.textContent=`录音反馈未生成：${error.message}`;}finally{button.disabled=false;button.textContent='重新评分这段录音';}}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音');return;}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(recordingUrl){URL.revokeObjectURL(recordingUrl);recordingUrl=null;}const player=$('#record-playback');if(player){player.pause();player.removeAttribute('src');player.hidden=true;}recordingBlob=null;recordingResult=null;recordingTopicId=st.topicId;const chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{recordStream?.getTracks().forEach(track=>track.stop());if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingBlob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});recordingUrl=URL.createObjectURL(recordingBlob);if(st.topicId!==recordingTopicId)return;const player=$('#record-playback');if(player){player.src=recordingUrl;player.hidden=false;}const button=$('[data-action="score-recording"]');if(button)button.disabled=!recordingBlob.size;const status=$('#record-status');if(status)status.textContent='录音结束，可回放或请求评分；刷新后消失。';};recorder.start();$('[data-action="record-start"]').disabled=true;$('[data-action="record-stop"]').disabled=false;$('#record-status').textContent='录音中…';const slot=$('#recording-feedback');if(slot)slot.innerHTML='';}catch{recordStream?.getTracks().forEach(track=>track.stop());toast('无法使用麦克风，请检查浏览器权限');}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();const start=$('[data-action="record-start"]'),stop=$('[data-action="record-stop"]');if(start)start.disabled=false;if(stop)stop.disabled=true;}
function sourceRows(items, detail){return items.length?items.map(x=>`<a class="link-row" href="${escapeHtml(x.url)}" target="_blank" rel="noopener noreferrer"><span><strong>${escapeHtml(x.date?`${x.date} · ${x.title}`:x.title)}</strong><small>${escapeHtml(detail(x))}</small></span><span class="arrow">↗</span></a>`).join(''):'<div class="empty">该月份尚无已核对的公开入口。</div>';}
function renderLibrary(){
 const season=sourceIndex.season,months=season.months;
 const keep=x=>st.month==='all'||x.month===st.month;
 const read=sourceIndex.reading.filter(keep),listen=sourceIndex.listening.filter(keep),writing=sourceIndex.writing.filter(keep),speaking=(sourceIndex.speaking||[]).filter(keep),leads=sourceIndex.recallLeads.filter(keep);
 const options=months.map(m=>`<option value="${m}" ${st.month===m?'selected':''}>${m}${sourceIndex.futureMonths.includes(m)?' · 待考试':''}</option>`).join('');
 const failed=sourceIndex.sourceStatus.filter(x=>x.status==='error');
 main.innerHTML=`${header('Public source index',`${season.label}公开题库目录`,'听力、口语、阅读、写作的公开来源索引。第三方回忆与重建练习仅供复习，考点和题目完整性以原站标注为准。',`<span class="badge blue">核对 ${escapeHtml(sourceIndex.checkedAt)}</span>`)}
 <div class="notice">1、5、9 月是本系统的四个月资料期切换点，不是雅思官方公布的听力、阅读、写作换题日期。跨期时只展示新期资料；已有个人作答记录保留在本浏览器。${failed.length?`本次有 ${failed.length} 个来源读取失败，同期已有条目会保留并标记。`:''}</div>
 <div class="toolbar" style="margin-top:20px"><select id="month-filter" aria-label="筛选月份"><option value="all" ${st.month==='all'?'selected':''}>本期全部</option>${options}</select></div>
 <div class="section-title"><h2>大陆口语话题 · ${speaking.length} 条</h2></div><div class="notice blue">来源网站标注为中国大陆话题；这里只列标题和 Part，具体题卡请回原站查看。</div><div class="link-list">${sourceRows(speaking,x=>`${x.part} · 第三方当期资料目录`)}</div>
 <div class="section-title"><h2>全国考点标注的写作话题 · ${writing.length} 条</h2></div><div class="link-list">${sourceRows(writing,x=>`${x.task} · ${x.venueReported||'未标考点'} · 第三方标注，未独立逐场核验`)}</div>
 <div class="section-title"><h2>国内相关及待核验的考情文章 · ${leads.length} 条</h2></div><div class="link-list">${sourceRows(leads,x=>`${x.geography==='mainland_or_asia_mixed_verify_article'?'包含亚太场，地点须回原文核对':'机构回忆/考情，地点以原文为准'} · 非完整原卷`)}</div>
 <div class="section-title"><h2>听力重建练习 · ${listen.length} 套</h2></div><div class="notice blue">此来源汇集全球考生回忆，未标具体中国考点；可用于练习，不能算作已核实的全国考点真题。</div><div class="link-list">${sourceRows(listen,()=>`第三方重建练习 · 音频和答案需联网`)}</div>
 <div class="section-title"><h2>阅读重建练习 · ${read.length} 套</h2></div><div class="link-list">${sourceRows(read,()=>`第三方重建练习 · 原文和答案需联网`)}</div>
 <div class="section-title"><h2>官方样题与来源状态</h2></div><div class="link-list"><a class="link-row" href="https://www.chinaielts.org/prepare/ielts-practice-tests/mocks-academic" target="_blank" rel="noopener noreferrer"><span><strong>IELTS 官方学术类样题</strong><small>听力、阅读、写作 · 非当期考后回忆</small></span><span class="arrow">↗</span></a></div>
 <p class="small muted">来源读取：${sourceIndex.sourceStatus.map(x=>`${escapeHtml(x.id)} ${escapeHtml(x.status)} ${x.items} 条`).join(' · ')}</p>`;
}
function allHistory(){return [...st.history,...(window.IELTS_PDF_IMPORT.historyEntries?.()||[])].sort((a,b)=>b.at-a.at);}
function historyAttempt(h){if(h.attempt)return h.attempt;const current=st[h.type];return current?.submittedAt&&`${h.type}-${current.startedAt}`===h.id?current:null;}
function historyNotes(attempt){
  const whole=Object.entries(attempt?.notes||{}).filter(([,value])=>String(value).trim()).map(([key,value])=>`<li><strong>${escapeHtml(key)}：</strong>${escapeHtml(value)}</li>`);
  const selected=Object.entries(attempt?.annotations||{}).flatMap(([key,items])=>(Array.isArray(items)?items:[]).filter(item=>item?.type==='note'&&item.text).map(item=>`<li><strong>${escapeHtml(key)} · ${escapeHtml(item.quote||'选中内容')}：</strong>${escapeHtml(item.text)}</li>`));
  return `<section class="panel history-notes"><h2>笔记</h2>${whole.length||selected.length?`<ul>${[...whole,...selected].join('')}</ul>`:'<p>这次练习没有保存笔记。</p>'}</section>`;
}
function historyQuestion(q,attempt,type){const key=type==='pdf'?(q.id||q.number):q.number;const answer=type==='writing'?(attempt.drafts?.[q.id]||''):(attempt.answers?.[key]||'');const expected=q.answer||'';const correct=expected&&isCorrect(answer,expected);const correction=attempt.corrections?.[key];return `<article class="review-card ${expected&&!correct?'wrong':''}"><h3>${escapeHtml(type==='writing'?q.name:`${q.number}. ${q.prompt}`)}</h3>${type==='writing'?`<p class="history-prompt">${escapeHtml(q.prompt)}</p>${q.columns?`<table class="writing-table"><thead><tr>${q.columns.map(v=>`<th>${escapeHtml(v)}</th>`).join('')}</tr></thead><tbody>${q.rows.map(row=>`<tr>${row.map(v=>`<td>${escapeHtml(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:''}`:(q.options?.length?`<p class="history-options">${q.options.map(escapeHtml).join('<br>')}</p>`:'')}<p><strong>${type==='writing'?'初稿':'你的答案'}：</strong></p><div class="history-answer">${escapeHtml(answer||'未作答')}</div>${type==='writing'?`<p><strong>修订稿：</strong></p><div class="history-answer">${escapeHtml(attempt.revisions?.[q.id]||'未填写')}</div><p class="small muted">写作题没有唯一标准答案。</p>`:`<p><strong>正确答案：</strong>${expected?escapeHtml(expected):'未提供标准答案'}</p>${correction!==undefined?`<p><strong>修正答案：</strong>${escapeHtml(correction||'未填写')}</p>`:''}${q.explanation?`<p><strong>解析：</strong>${escapeHtml(q.explanation)}</p>`:''}`}</article>`;}
function renderHistoryDetail(h){
  const attempt=historyAttempt(h),paper=h.paper||(h.type==='reading'?test:h.type==='listening'?listeningTest:writingTest);
  const questions=h.type==='pdf'?h.questions:paper.questions||paper.tasks;
  const summary=h.type==='writing'?`${(h.words||[]).join(' / ')} 词`:h.type==='pdf'?`${questions?.length||0} 题`:`${h.score} / ${h.total}`;
  main.innerHTML=`${header('Practice history',h.title,`${dateText(h.at)} · ${summary}`)}<div class="toolbar"><button class="btn secondary" data-action="history-back">← 返回记录</button><button class="btn" data-action="history-redo">重新做</button></div>${attempt&&questions&&(h.type==='pdf'||h.paper||attempt.testId===paper.id)?`${h.type==='reading'&&paper.passages?paper.passages.map((p,i)=>`<details class="panel history-reference"><summary>Passage ${i+1} · ${escapeHtml(p.title)}</summary>${p.paragraphs.map(x=>`<p><strong>${escapeHtml(x.label)}</strong> ${escapeHtml(x.text)}</p>`).join('')}</details>`).join(''):''}${h.type==='listening'&&paper.sections?paper.sections.map((s,i)=>`<details class="panel history-reference"><summary>Section ${i+1} · ${escapeHtml(s.title)} 文字稿</summary><p>${escapeHtml(s.transcript)}</p></details>`).join(''):''}${h.type==='pdf'&&h.referenceText?`<details class="panel history-reference"><summary>PDF 提取原文</summary><pre>${escapeHtml(h.referenceText)}</pre></details>`:''}${questions.map(q=>historyQuestion(q,attempt,h.type)).join('')}${historyNotes(attempt)}`:'<div class="notice">这条旧记录只保存了成绩或字数，详细作答或当时的题目已不可用，无法恢复。可以重新做这份练习。</div>'}`;
}
function renderHistory(){const entries=allHistory(),selected=entries.find(h=>h.id===st.historyId);if(selected){renderHistoryDetail(selected);return;}st.historyId=null;main.innerHTML=`${header('Practice history','练习记录','点击记录查看当次题目、你的答案、正确答案和笔记；重新做会保留已提交的记录。')}<div class="panel">${entries.length?entries.map(h=>`<button type="button" class="history-item" data-history-id="${escapeHtml(h.id)}"><span><strong>${escapeHtml(h.title)}</strong><small>${dateText(h.at)} · ${escapeHtml({reading:'阅读',listening:'听力',writing:'写作',pdf:'PDF'}[h.type]||h.type)}</small></span><span class="badge blue">${h.type==='writing'?`${(h.words||[]).join(' / ')} 词`:h.type==='pdf'?`${h.questions?.length||0} 题`:`${h.score} / ${h.total}`}</span></button>`).join(''):'<div class="empty">暂无练习记录。</div>'}</div>`;}
function render(){switch(st.view){case'season':window.IELTS_SEASON_BANK.render(main,sourceIndex,st.capabilities);break;case'reading':renderReading();break;case'listening':renderListening();break;case'writing':renderWriting();break;case'speaking':renderSpeaking();break;case'pdf':window.IELTS_PDF_IMPORT.render();break;case'library':renderLibrary();break;case'history':renderHistory();break;default:renderHome();}}
function tick(){if(st.reading&&!st.reading.submittedAt){const ms=deadlineMs(),time=$('#reading-timer');if(time){time.textContent=timerText(ms);time.classList.toggle('low',ms<60000);}if(ms<=0)submitReading(true);}if(st.listening&&!st.listening.submittedAt){const ms=st.listening.deadlineAt-Date.now(),time=$('#listening-timer');if(time){time.textContent=timerText(ms);time.classList.toggle('low',ms<60000);}if(ms<=0)submitListening(true);}if(st.writing&&!st.writing.submittedAt){const ms=st.writing.deadlineAt-Date.now(),time=$('#writing-timer');if(time){time.textContent=timerText(ms);time.classList.toggle('low',ms<60000);}if(ms<=0)submitWriting(true);}}
document.addEventListener('click',e=>{const n=e.target.closest('[data-view]');if(n){nav(n.dataset.view);return;}const a=e.target.closest('[data-action]');if(a){switch(a.dataset.action){case'open-season':nav('season');break;case'open-reading':nav('reading');break;case'open-listening':nav('listening');break;case'open-writing':nav('writing');break;case'open-library':nav('library');break;case'start-reading':startReading();break;case'submit-reading':submitReading();break;case'font-decrease':case'font-increase':{const delta=a.dataset.action==='font-increase'?2:-2;st.reading.fontSize=Math.min(22,Math.max(14,(st.reading.fontSize||16)+delta));save(STORE.reading,st.reading);$('#passage-scroll')?.style.setProperty('--passage-font',`${st.reading.fontSize}px`);$('#passage-font-label').textContent=`${st.reading.fontSize}px`;break;}case'prev-passage':st.passage=Math.max(0,st.passage-1);st.selectedQuestion=test.questions.find(q=>q.passage===test.passages[st.passage].id).number;renderExam();break;case'next-passage':st.passage=Math.min(2,st.passage+1);st.selectedQuestion=test.questions.find(q=>q.passage===test.passages[st.passage].id).number;renderExam();break;case'export-result':download('ielts-reading-result.json',{test:test.id,submittedAt:st.reading.submittedAt,initialScore:score(),answers:st.reading.answers,corrections:st.reading.corrections});break;case'restart-reading':if(window.confirm('重新开始会清空当前阅读练习区；已提交的答案和笔记会保留在练习记录中。继续吗？'))startReading();break;case'start-listening':startListening();break;case'submit-listening':submitListening();break;case'export-listening':download('ielts-listening-result.json',{test:listeningTest.id,submittedAt:st.listening.submittedAt,initialScore:listenScore(),answers:st.listening.answers,corrections:st.listening.corrections});break;case'restart-listening':if(window.confirm('重新开始会清空当前听力练习区；已提交的答案和笔记会保留在练习记录中。继续吗？'))startListening();break;case'correct-listening':correctListening(Number(a.dataset.number));break;case'start-writing':startWriting();break;case'submit-writing':submitWriting();break;case'export-writing':download('ielts-writing-result.json',{test:writingTest.id,submittedAt:st.writing.submittedAt,drafts:st.writing.drafts,revisions:st.writing.revisions,checks:st.writing.checks});break;case'restart-writing':if(window.confirm('重新开始会清空当前写作练习区；已提交的初稿和修订稿会保留在练习记录中。继续吗？'))startWriting();break;}return;}const j=e.target.closest('[data-jump]');if(j){const number=Number(j.dataset.jump),q=qByNum.get(number);st.selectedQuestion=number;st.passage=test.passages.findIndex(p=>p.id===q.passage);renderExam();return;}const lj=e.target.closest('[data-listen-jump]');if(lj){st.listenSection=Math.floor((Number(lj.dataset.listenJump)-1)/10);renderListening();return;}const f=e.target.closest('[data-flag]');if(f){const number=Number(f.dataset.flag),set=new Set(st.reading.flags);set.has(number)?set.delete(number):set.add(number);st.reading.flags=[...set];save(STORE.reading,st.reading);renderExam();return;}const c=e.target.closest('[data-correct]');if(c){correctQuestion(Number(c.dataset.correct));return;}const wt=e.target.closest('[data-write-task]');if(wt){st.writeTask=Number(wt.dataset.writeTask);renderWriting();return;}});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-passage-note]')&&st.reading){st.reading.notes??={};st.reading.notes[el.dataset.passageNote]=el.value;save(STORE.reading,st.reading);annotations.refreshDrawer('reading');}if(el.matches('[data-answer]')&&el.type==='text'){st.reading.answers[el.dataset.answer]=el.value;save(STORE.reading,st.reading);updateProgress();}if(el.matches('[data-listen-answer]')&&el.type==='text'){st.listening.answers[el.dataset.listenAnswer]=el.value;save(STORE.listening,st.listening);updateListeningProgress();}if(el.id==='writing-draft'&&st.writing){const id=writingTest.tasks[st.writeTask].id;st.writing.drafts[id]=el.value;save(STORE.writing,st.writing);$('#writing-word-count').textContent=wordCount(el.value);}if(el.matches('[data-write-revision]')&&st.writing){st.writing.revisions[el.dataset.writeRevision]=el.value;save(STORE.writing,st.writing);$(`[data-revision-count="${el.dataset.writeRevision}"]`).textContent=wordCount(el.value);}});
document.addEventListener('click',e=>{
  const row=e.target.closest('[data-history-id]');
  if(row){st.historyId=row.dataset.historyId;renderHistory();window.scrollTo(0,0);return;}
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='history-back'){st.historyId=null;renderHistory();window.scrollTo(0,0);return;}
  if(action!=='history-redo')return;
  const entry=allHistory().find(item=>item.id===st.historyId);
  if(!entry||!window.confirm('开始新一轮作答？已提交的答案和笔记会保留在练习记录中。'))return;
  if(entry.type==='pdf'){if(window.IELTS_PDF_IMPORT.redoHistory(entry.paperId))nav('pdf');return;}
  if(entry.type==='reading'){nav('reading');startReading();}
  if(entry.type==='listening'){nav('listening');startListening();}
  if(entry.type==='writing'){nav('writing');startWriting();}
});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-answer]')&&el.type==='radio'){st.reading.answers[el.dataset.answer]=el.value;save(STORE.reading,st.reading);updateProgress();}if(el.matches('[data-listen-answer]')&&el.type==='radio'){st.listening.answers[el.dataset.listenAnswer]=el.value;save(STORE.listening,st.listening);updateListeningProgress();}if(el.matches('[data-write-check]')&&st.writing){st.writing.checks[el.dataset.writeCheck]=el.checked;save(STORE.writing,st.writing);}if(el.id==='month-filter'){st.month=el.value;renderLibrary();}});
function updateProgress(){const count=Object.values(st.reading.answers).filter(v=>normalize(v)).length;const e=$('#reading-progress');if(e)e.textContent=`已答 ${count} / 40`;document.querySelectorAll('[data-jump]').forEach(b=>b.classList.toggle('answered',!!normalize(st.reading.answers[b.dataset.jump])));}
function updateListeningProgress(){const count=Object.values(st.listening.answers).filter(v=>normalize(v)).length;const e=$('#listening-progress');if(e)e.textContent=`已答 ${count} / 40`;document.querySelectorAll('[data-listen-jump]').forEach(b=>b.classList.toggle('answered',!!normalize(st.listening.answers[b.dataset.listenJump])));}
document.addEventListener('click',e=>{const ai=e.target.closest('[data-ai-kind]');if(ai){requestFeedback(ai);return;}const sentence=e.target.closest('[data-sentence-src]');if(sentence){const panel=sentence.closest('.sentence-panel'),player=$('audio',panel);panel.querySelectorAll('.sentence-button').forEach(button=>button.classList.toggle('active',button===sentence));player.src=sentence.dataset.sentenceSrc;player.play().catch(()=>toast('播放失败，请检查本地音频文件'));return;}const topic=e.target.closest('[data-topic-id]');if(topic){if(recorder?.state==='recording')stopRecording();st.topicId=topic.dataset.topicId;renderSpeaking();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='open-speaking')nav('speaking');if(action==='toggle-wrong'){st.wrongOnly=!st.wrongOnly;render();}if(action==='record-start')startRecording();if(action==='record-stop')stopRecording();if(action==='score-recording')requestRecordingFeedback(e.target.closest('button'));});
document.addEventListener('input',e=>{if(e.target.id==='speaking-transcript'&&st.topicId){st.speaking[st.topicId]=e.target.value;save(STORE.speaking,st.speaking);const key=`speaking-${st.topicId}`;if(st.feedback[key]){delete st.feedback[key];save(STORE.feedback,st.feedback);$(`#feedback-${CSS.escape(key)}`).innerHTML='';}}if(e.target.matches('[data-write-revision]')){const key=`writing-${e.target.dataset.writeRevision}`;if(st.feedback[key]){delete st.feedback[key];save(STORE.feedback,st.feedback);$(`#feedback-${CSS.escape(key)}`).innerHTML='';}}if(e.target.id==='topic-search')filterTopics();});
document.addEventListener('change',e=>{if(e.target.id==='part-filter'){st.part=e.target.value;filterTopics();}});
$('#contrast-toggle').addEventListener('click',()=>{document.body.classList.toggle('high-contrast');save(STORE.contrast,document.body.classList.contains('high-contrast'));});
async function refreshSourceIndex(){if(!location.protocol.startsWith('http'))return;try{const response=await fetch('data/public-index.json',{cache:'no-store'});if(!response.ok)return;const next=await response.json();if(next.schemaVersion!==3||!next.season||JSON.stringify(next)===JSON.stringify(sourceIndex))return;const changedSeason=next.season.id!==sourceIndex.season.id;sourceIndex=next;if(changedSeason){st.month='all';st.topicId=null;}updateSourceLabels();if(['season','home','library','speaking'].includes(st.view))render();}catch{}}
window.addEventListener('ielts:open-speaking',event=>{st.topicId=event.detail;nav('speaking');});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshSourceIndex();refreshCapabilities();}});
setInterval(tick,500);setInterval(refreshSourceIndex,300000);render();tick();refreshSourceIndex();refreshCapabilities();
})();
